{
  "name": "opencode-zerodahero",
  "version": "0.5.0",
  "description": "opencode plugin for zerodahero-skills: adds the second-review skill and the /second-review command.",
  "type": "module",
  "files": [
    "opencode/",
    "skills/review/second-review/"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "code-review"
  ],
  "author": "Zack Teska (https://github.com/zerodahero)",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/zerodahero/agent-kit.git"
  },
  "license": "MIT",
  "exports": {
    ".": "./opencode/plugin.js"
  },
  "dependencies": {
    "@opencode/plugin": "^2.2.5"
  }
}

// opencode v2 plugin: registers the second-review skill and the /second-review command.
// Both are built from the skill files in this package, so the skill stays the single
// source for what the reviewer does. The second-reviewer agent ships separately as
// opencode/agents/second-reviewer.md, because plugins cannot add agents.
import { readFile } from "node:fs/promises"
import { fileURLToPath } from "node:url"
import { Plugin, Skill } from "@opencode/plugin"

const skillDir = new URL("../skills/review/second-review/", import.meta.url)
const skillPath = fileURLToPath(new URL("SKILL.md", skillDir))

const description =
  "Review this branch as an independent second reviewer and write the findings to a file for the primary agent"

function stripFrontmatter(text) {
  return text.replace(/^---\n[\s\S]*?\n---\n+/, "")
}

// The SKILL.md body with REVIEW-METHOD.md appended, so one prompt carries everything.
async function buildContent() {
  const [skill, method] = await Promise.all([
    readFile(new URL("SKILL.md", skillDir), "utf8"),
    readFile(new URL("REVIEW-METHOD.md", skillDir), "utf8"),
  ])
  const body = stripFrontmatter(skill).replaceAll(
    "[REVIEW-METHOD.md](REVIEW-METHOD.md)",
    "the Review method section below",
  )
  return `${body.trimEnd()}\n\n## Review method\n\n${method}`
}

export default Plugin.define({
  id: "zerodahero.second-review",
  async setup(ctx) {
    const content = await buildContent()

    await ctx.skill.transform((editor) => {
      if (editor.get("second-review")) return
      editor.add({
        id: Skill.ID.make("second-review"),
        name: Skill.Name.make("second-review"),
        description,
        autoinvoke: false,
        path: skillPath,
        content,
      })
    })

    await ctx.command.transform((editor) => {
      editor.add({
        name: "second-review",
        description,
        async execute({ sessionID, prompt }) {
          const args = (prompt?.text ?? "").trim()
          // The server resolves the agent in the session's own project, so a global or a
          // project-level second-reviewer both work. Without one, stay on the current agent.
          try {
            await ctx.session.switchAgent({ sessionID, agent: "second-reviewer" })
          } catch {}
          await ctx.session.prompt({
            sessionID,
            text: content.replaceAll("$ARGUMENTS", args || "(none)"),
          })
        },
      })
    })
  },
})

---
description: Red-teams a plan in plan mode. Reads the repo and writes one report file per round.
mode: subagent
permissions:
  - { action: "*", resource: "*", effect: deny }
  - { action: read, resource: "*", effect: allow }
  - { action: glob, resource: "*", effect: allow }
  - { action: grep, resource: "*", effect: allow }
  - { action: edit, resource: ".claude/plan/plan-review-*", effect: allow }
  - { action: shell, resource: "git diff*", effect: allow }
  - { action: shell, resource: "git log*", effect: allow }
  - { action: shell, resource: "git show*", effect: allow }
  - { action: shell, resource: "git status*", effect: allow }
  - { action: shell, resource: "git rev-parse*", effect: allow }
  - { action: shell, resource: "git rev-list*", effect: allow }
  - { action: shell, resource: "git branch --show-current", effect: allow }
  - { action: shell, resource: "git merge-base*", effect: allow }
  - { action: shell, resource: "git ls-files*", effect: allow }
  - { action: shell, resource: "git grep*", effect: allow }
  - { action: shell, resource: "rg *", effect: allow }
  - { action: shell, resource: "grep *", effect: allow }
  - { action: shell, resource: "ls*", effect: allow }
  - { action: shell, resource: "wc *", effect: allow }
  - { action: shell, resource: "* --output*", effect: deny }
  - { action: shell, resource: "rg *--pre*", effect: deny }
  - { action: shell, resource: "git grep *-O*", effect: deny }
  - { action: shell, resource: "git grep *--open-files-in-pager*", effect: deny }
  - { action: external_directory, resource: "*", effect: deny }
  - { action: question, resource: "*", effect: deny }
  - { action: subagent, resource: "*", effect: deny }
  - { action: webfetch, resource: "*", effect: deny }
  - { action: websearch, resource: "*", effect: deny }
---

You are a plan reviewer. You red-team a plan that another agent wrote, over several
rounds in this one session. The first round's message attaches PLAN-REVIEW-METHOD.md.
Follow it exactly in every round. Your own session history is your memory of earlier
rounds.

You read the repo and write one report per round, at the path the round's message names.
That report is the only file you write.

Your shell runs only these, one command per call: `git diff`, `git log`, `git show`,
`git status`, `git rev-parse`, `git rev-list`, `git merge-base`, `git ls-files`,
`git grep`, `git branch --show-current`, `rg`, `grep`, `ls`, `wc`. Any other command, or a
chain of commands joined by `;`, `&&` or a pipe, is denied. List every denied call in
your report, as the method says. A denial missing from the report fails the round.
